"""gcu400 diagonal_copy: dedicated gather-copy kernel over the diagonal view.

The generic pointwise-dynamic copy runs the strided (diagonal) view through a
block-pointer kernel capped at 12 CTAs (utils codegen config for enflame), so
the scattered diagonal loads cannot hide their latency on a 48-SP device.
This kernel keeps the same single launch but parallelizes over
min(48, work_items) programs with a grid-stride loop; each work item copies one
BLOCK_J chunk of one outer row:

  src = x + row_base + (col0 + j) * diag_stride   (scattered, 1 transaction each)
  dst = out + row * L + j                          (contiguous, vectorizable)

Fallbacks to the generic pointwise copy for >3 outer dims (x.ndim > 5) or when
any computed offset exceeds the int32 range used inside the kernel.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry, pointwise_dynamic

logger = logging.getLogger(__name__)

_NUM_SPS = 48
_MAX_BLOCK_J = 512
_MIN_BLOCK_J = 16
_INT32_MAX = 2**31 - 1


@pointwise_dynamic(is_tensor=[True], promotion_methods=[(0, "DEFAULT")])
@triton.jit
def copy_func(x):
    return x


@libentry()
@triton.jit
def diagonal_copy_kernel(
    x_ptr,
    out_ptr,
    R,  # flattened outer-row count
    L,  # diagonal length
    ncc,  # column chunks per row
    diag_stride,  # view stride along the diagonal
    s0,
    s1,
    s2,  # outer strides (padded with zeros)
    d1,
    d2,  # outer sizes (padded with ones)
    BLOCK: tl.constexpr,
    NPROG: tl.constexpr,
    NEED_MASK: tl.constexpr,
):
    pid = tl.program_id(0)
    if NEED_MASK:
        total = R * ncc
        for w in range(pid, total, NPROG):
            row = w // ncc
            c = w - row * ncc
            j = c * BLOCK + tl.arange(0, BLOCK)
            mask = j < L
            r2 = row % d2
            t = row // d2
            r1 = t % d1
            r0 = t // d1
            src = x_ptr + (r0 * s0 + r1 * s1 + r2 * s2) + j * diag_stride
            v = tl.load(src, mask=mask)
            tl.store(out_ptr + row * L + j, v, mask=mask)
    else:
        tiles_per_row = L // BLOCK
        total = R * tiles_per_row
        for t_id in range(pid, total, NPROG):
            base = t_id * BLOCK
            row = base // L
            col0 = base - row * L
            r2 = row % d2
            t = row // d2
            r1 = t % d1
            r0 = t // d1
            offs = tl.arange(0, BLOCK)
            src = x_ptr + (r0 * s0 + r1 * s1 + r2 * s2) + (col0 + offs) * diag_stride
            v = tl.load(src)
            tl.store(out_ptr + base + offs, v)


def _next_pow2(n):
    return 1 << max(n - 1, 0).bit_length()


def diagonal_copy(
    self: torch.Tensor, offset: int = 0, dim1: int = 0, dim2: int = 1
) -> torch.Tensor:
    """
    Performs the same operation as torch.diagonal, but returns a copy instead of a view.
    """
    logger.debug("GEMS_ENFLAME DIAGONAL_COPY")

    # Validate dimensions
    ndim = self.ndim
    dim1 = dim1 if dim1 >= 0 else dim1 + ndim
    dim2 = dim2 if dim2 >= 0 else dim2 + ndim

    if dim1 == dim2:
        raise ValueError("dim1 and dim2 must be different")

    # Use torch.diagonal to get a view of the diagonal
    # Then copy it into a densely packed output with a dedicated kernel.
    # The output must be contiguous: torch.diagonal_copy always returns a densely
    # packed tensor, and empty_like(diag_view) would inherit the view's strided
    # layout, which pointwise_dynamic cannot store to on this backend.
    diag_view = torch.diagonal(self, offset=offset, dim1=dim1, dim2=dim2)
    output = torch.empty(
        diag_view.shape, dtype=diag_view.dtype, device=diag_view.device
    )

    if output.numel() == 0:
        return output

    view_ndim = diag_view.ndim
    if view_ndim <= 4:
        L = diag_view.shape[-1]
        outer_sizes = list(diag_view.shape[:-1])
        outer_strides = list(diag_view.stride()[:-1])
        R = 1
        for size in outer_sizes:
            R *= size
        diag_stride = diag_view.stride(-1)
        sizes = outer_sizes + [1] * (3 - len(outer_sizes))
        strides = outer_strides + [0] * (3 - len(outer_strides))
        max_row_off = sum((d - 1) * s for d, s in zip(sizes, strides))
        if (
            max_row_off + (L - 1) * diag_stride <= _INT32_MAX
            and R * L - 1 <= _INT32_MAX
        ):
            block = max(_MIN_BLOCK_J, min(_MAX_BLOCK_J, _next_pow2(L)))
            if L % block == 0:
                need_mask = False
                ncc = L // block
            else:
                need_mask = True
                ncc = triton.cdiv(L, block)
            tiles = R * ncc
            nprog = min(_NUM_SPS, tiles)
            num_warps = 1 if tiles <= _NUM_SPS else 2
            with torch_device_fn.device(diag_view.device.index):
                diagonal_copy_kernel[(nprog,)](
                    diag_view,
                    output,
                    R,
                    L,
                    ncc,
                    diag_stride,
                    strides[0],
                    strides[1],
                    strides[2],
                    sizes[1],
                    sizes[2],
                    BLOCK=block,
                    NPROG=nprog,
                    NEED_MASK=need_mask,
                    num_warps=num_warps,
                )
            return output

    # Fallback: generic pointwise copy (more than 3 outer dims, or offsets
    # beyond the int32 addressing range used by the dedicated kernel).
    overload = copy_func.instantiate(view_ndim)
    overload(diag_view, out0=output)
    return output
